import numpy as np

def template_match_ssd(image, template):
    image = np.asarray(image, dtype=np.float64)
    template = np.asarray(template, dtype=np.float64)
    H, W = image.shape
    h, w = template.shape
    best_ssd = float('inf')
    best_x, best_y = 0, 0
    for y in range(H - h + 1):
        for x in range(W - w + 1):
            window = image[y:y + h, x:x + w]
            ssd = float(((window - template) ** 2).sum())
            if ssd < best_ssd:
                best_ssd = ssd
                best_x, best_y = x, y
    return (best_x, best_y)
